// Matchup difficulty - how many fantasy points a defense gives up to a
// position, relative to what the players it faced usually score. See
// infinileague/scripts/matchup-difficulty/backtest.py (and its results.md)
// for the method and why it's shaped this way; the constants in
// matchupCalibration.ts are generated by that script.
//
// Stored scoring-free (defenseMatchupSets keeps raw stat sums, built by
// buildDefenseMatchups below) and scored per request in the league's own
// scoring (gradeDefenseMatchups) - never stored per scoring combo.
//
// Display-only: Sleeper's projections already price matchups in (the
// backtest found ~0 gain from layering this on top of them), so nothing
// feeds this into a projection.

import type { ScoringConfig } from "../scoring";
import {
  MATCHUP_CALIBRATION,
  MATCHUP_CATEGORIES,
  MATCHUP_MIN_OTHER_GAMES,
  MATCHUP_SHRINKAGE,
  type MatchupCategory,
  type MatchupPosition,
} from "./matchupCalibration";

export type { MatchupCategory, MatchupPosition };

export function isMatchupPosition(position: string): position is MatchupPosition {
  return position in MATCHUP_CATEGORIES;
}

// The raw stats behind each category's points - all a category's scoring
// needs, so the stored sums can be scored in any league's settings.
const CATEGORY_STATS: Record<MatchupCategory, string[]> = {
  pass: ["pass_yd", "pass_td", "pass_int"],
  rush: ["rush_yd", "rush_td"],
  rec: ["rec", "rec_yd", "rec_td"],
};

const REC_POINTS: Record<ScoringConfig["scoring"], number> = { STD: 0, HALF: 0.5, PPR: 1 };
const TE_REC_BONUS: Record<ScoringConfig["teScoring"], number> = { NONE: 0, HALF: 0.5, FULL: 1 };

export function positionStatKeys(position: MatchupPosition): string[] {
  return MATCHUP_CATEGORIES[position].flatMap((category) => CATEGORY_STATS[category]);
}

// One category's points from a stat line (or a sum of them) - the same
// coefficients as scoring.ts's computeProjectedPoints + bonusPoints.
export function categoryPoints(
  stats: Record<string, number>,
  category: MatchupCategory,
  position: MatchupPosition,
  config: ScoringConfig,
): number {
  const s = (key: string) => stats[key] ?? 0;
  if (category === "pass") {
    return s("pass_yd") * 0.04 + s("pass_td") * (config.sixPointPassTds ? 6 : 4) - s("pass_int");
  }
  if (category === "rush") return s("rush_yd") * 0.1 + s("rush_td") * 6;
  const perRec = REC_POINTS[config.scoring] + (position === "TE" ? TE_REC_BONUS[config.teScoring] : 0);
  return s("rec") * perRec + s("rec_yd") * 0.1 + s("rec_td") * 6;
}

// ---------------------------------------------------------------- build

export interface MatchupGame {
  fpid: number;
  position: MatchupPosition;
  week: number;
  // The defense he faced (Sleeper's team code).
  opponent: string;
  // positionStatKeys(position) only.
  stats: Record<string, number>;
}

// One defense's record against one position: the raw stats it allowed, and
// what the same players' baselines expected (summed game by game).
// Built rows are always MatchupPosition; grading takes any position string
// so stored rows (typed as every position) pass straight in.
export interface DefenseMatchupRow<P extends string = string> {
  defense: string;
  position: P;
  games: number;
  allowed: Record<string, number>;
  baseline: Record<string, number>;
}

function addInto(target: Record<string, number>, stats: Record<string, number>, scale = 1) {
  for (const [key, value] of Object.entries(stats)) {
    target[key] = (target[key] ?? 0) + value * scale;
  }
}

const round2 = (value: number) => Math.round(value * 100) / 100;

// Every defense's record through `throughWeek`. A game's baseline is the
// player's average over his other games that season up to then, leaving
// out every game against this same defense - so a defense never grades
// itself. Games without MATCHUP_MIN_OTHER_GAMES other games are skipped.
export function buildDefenseMatchups(
  games: MatchupGame[],
  throughWeek: number,
): Array<DefenseMatchupRow<MatchupPosition>> {
  const byPlayer = new Map<number, MatchupGame[]>();
  for (const game of games) {
    if (game.week > throughWeek) continue;
    const list = byPlayer.get(game.fpid);
    if (list) list.push(game);
    else byPlayer.set(game.fpid, [game]);
  }

  const rows = new Map<string, DefenseMatchupRow<MatchupPosition>>();
  for (const history of byPlayer.values()) {
    // Leave-one-out sums: everything, minus the games against each opponent.
    const total: Record<string, number> = {};
    const byOpponent = new Map<string, { count: number; stats: Record<string, number> }>();
    for (const game of history) {
      addInto(total, game.stats);
      const entry = byOpponent.get(game.opponent) ?? { count: 0, stats: {} };
      entry.count += 1;
      addInto(entry.stats, game.stats);
      byOpponent.set(game.opponent, entry);
    }

    for (const game of history) {
      const against = byOpponent.get(game.opponent)!;
      const others = history.length - against.count;
      if (others < MATCHUP_MIN_OTHER_GAMES) continue;
      const key = `${game.opponent}|${game.position}`;
      const row = rows.get(key) ?? {
        defense: game.opponent,
        position: game.position,
        games: 0,
        allowed: {},
        baseline: {},
      };
      row.games += 1;
      addInto(row.allowed, game.stats);
      for (const stat of positionStatKeys(game.position)) {
        row.baseline[stat] = (row.baseline[stat] ?? 0) + ((total[stat] ?? 0) - (against.stats[stat] ?? 0)) / others;
      }
      rows.set(key, row);
    }
  }

  // Rounded and sorted so an unchanged rebuild compares equal to the stored set.
  const roundAll = (stats: Record<string, number>) =>
    Object.fromEntries(Object.entries(stats).map(([key, value]) => [key, round2(value)]));
  return [...rows.values()]
    .map((row) => ({ ...row, allowed: roundAll(row.allowed), baseline: roundAll(row.baseline) }))
    .sort((a, b) => (a.defense === b.defense ? a.position.localeCompare(b.position) : a.defense.localeCompare(b.defense)));
}

// ---------------------------------------------------------------- grade

export type MatchupTier = "easy" | "hard" | "neutral";

export interface CategoryGrade {
  category: MatchupCategory;
  // Damped, like the overall factor - 1.05 = 5% more than usual.
  factor: number;
  // 1 = easiest of the `of` defenses graded at this position.
  rank: number;
}

export interface DefenseMatchupGrade {
  defense: string;
  position: MatchupPosition;
  // Expected points vs. a player's usual, damped (MATCHUP_CALIBRATION) -
  // 1.04 = about 4% more than usual. The color and number.
  factor: number;
  tier: MatchupTier;
  rank: number;
  // Defenses graded at this position - the denominator for every rank.
  of: number;
  games: number;
  categories: CategoryGrade[];
}

function shrunk(allowed: number, baseline: number): number {
  return (allowed + MATCHUP_SHRINKAGE) / (baseline + MATCHUP_SHRINKAGE);
}

// Rank 1 = the highest factor (easiest), ties share a rank.
function rankDescending(values: number[]): number[] {
  return values.map((value) => 1 + values.filter((other) => other > value).length);
}

// Every defense-position in a stored set, scored in this league's scoring.
export function gradeDefenseMatchups(rows: DefenseMatchupRow[], config: ScoringConfig): DefenseMatchupGrade[] {
  const grades: DefenseMatchupGrade[] = [];
  for (const position of Object.keys(MATCHUP_CATEGORIES) as MatchupPosition[]) {
    const atPosition = rows.filter((row) => row.position === position);
    if (atPosition.length === 0) continue;
    const { damping, hard, easy, colored } = MATCHUP_CALIBRATION[position];
    const damp = (raw: number) => 1 + damping * (raw - 1);
    const categories = MATCHUP_CATEGORIES[position];

    const scored = atPosition.map((row) => {
      const perCategory = categories.map((category) => ({
        allowed: categoryPoints(row.allowed, category, position, config),
        baseline: categoryPoints(row.baseline, category, position, config),
      }));
      const allowed = perCategory.reduce((sum, part) => sum + part.allowed, 0);
      const baseline = perCategory.reduce((sum, part) => sum + part.baseline, 0);
      return {
        row,
        factor: damp(shrunk(allowed, baseline)),
        categoryFactors: perCategory.map((part) => damp(shrunk(part.allowed, part.baseline))),
      };
    });

    const ranks = rankDescending(scored.map((entry) => entry.factor));
    const categoryRanks = categories.map((_, i) => rankDescending(scored.map((entry) => entry.categoryFactors[i]!)));
    scored.forEach((entry, index) => {
      const change = entry.factor - 1;
      grades.push({
        defense: entry.row.defense,
        position,
        factor: round4(entry.factor),
        tier: !colored ? "neutral" : change >= easy ? "easy" : change <= hard ? "hard" : "neutral",
        rank: ranks[index]!,
        of: scored.length,
        games: entry.row.games,
        categories: categories.map((category, i) => ({
          category,
          factor: round4(entry.categoryFactors[i]!),
          rank: categoryRanks[i]![index]!,
        })),
      });
    });
  }
  return grades;
}

function round4(value: number): number {
  return Math.round(value * 10000) / 10000;
}
